<?php
session_start();
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
function h($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$host='127.0.0.1'; $port='3306'; $dbname='kanji_master'; $dbUser='root'; $dbPassword='root';
$error=''; $kanjiRows=[]; $selectedId=isset($_GET['kanji_id'])?(int)$_GET['kanji_id']:0;
try {
  $pdo=new PDO("mysql:host=$host;port=$port;dbname=$dbname;charset=utf8mb4",$dbUser,$dbPassword,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
  $kanjiRows=$pdo->query('SELECT id, kanji_character, meaning, on_reading, kun_reading, jlpt_level, stroke_count FROM kanji ORDER BY FIELD(jlpt_level, \'N5\', \'N4\', \'N3\', \'N2\', \'N1\'), kanji_character ASC')->fetchAll();
  if ($selectedId && !array_filter($kanjiRows,fn($r)=>(int)$r['id']===$selectedId)) $selectedId=0;
} catch(PDOException $e) {
  error_log('Kanji Master practice page error: '.$e->getMessage());
  $error=strpos($e->getMessage(),'Access denied')!==false?'Database login failed. Check the MySQL username and password in practice.php.':(strpos($e->getMessage(),'Unknown database')!==false?'The kanji_master database was not found.':'Could not load kanji. Confirm MySQL is running and the kanji table has the expected columns.');
}
$selectedKanji=null;
foreach($kanjiRows as $r) if((int)$r['id']===$selectedId) {$selectedKanji=$r;break;}
if(!$selectedKanji && $kanjiRows){$selectedKanji=$kanjiRows[0];$selectedId=(int)$selectedKanji['id'];}
?>
