nd:white;color:var(--ink);font-size:13px;outline:none}.kanji-summary{display:grid;grid-template-columns:88px minmax(0,1fr);gap:13px;align-items:center;padding:14px 0 2px}.big-kanji{width:88px;height:88px;background:linear-gradient(145deg,#f2f2ff,#f8f9ff);border:1px solid #e7e6ff;border-radius:16px;display:grid;place-items:center;font-size:56px;line-height:1}.meaning{font-size:16px;font-weight:800;margin-bottom:5px}.reading{font-size:12px;color:var(--muted);margin:3px 0;overflow-wrap:anywhere}.meta-row{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.meta{background:#f3f5f9;border-radius:7px;padding:4px 7px;color:#596478;font-size:10px;font-weight:800}.stepper{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:13px;padding-top:12px;border-top:1px solid var(--line)}.stepper span{font-size:11px;color:var(--muted)}.stepper .btn{padding:8px 10px}.stroke-content{padding:14px 16px 15px}.stroke-stage{width:100%;max-width:230px;aspect-ratio:1;margin:0 auto 12px;background:#fafbff;border:1px solid var(--line);border-radius:15px;display:grid;place-items:center;overflow:hidden}.stroke-stage svg{width:100%;height:100%;padding:9px}.stroke-stage .placeholder{font-size:12px;color:var(--muted);text-align:center;padding:18px}.stroke-controls{display:grid;grid-template-columns:1fr 1fr 1fr;gap:7px}.stroke-controls .btn{padding:9px 5px;font-size:11px}.stroke-status{text-align:center;color:var(--muted);font-size:11px;min-height:16px;margin:10px 0 0}.credit{font-size:10px;color:#8a93a5;line-height:1.5;margin:10px 0 0}.history{margin-top:16px}.history .card-head{padding:12px 16px}.history-body{padding:10px 14px 13px}.history-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.history-item{display:flex;align-items:center;gap:9px;min-width:0;padding:8px;background:#fafbfe;border:1px solid #edf0f5;border-radius:10px}.history-char{font-size:23px;font-weight:700;width:30px;text-align:center;flex-shrink:0}.history-detail{min-width:0}.history-detail strong{display:block;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.history-detail small{display:block;color:var(--muted);font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.empty-history{font-size:12px;color:var(--muted);padding:5px 0}.notice{padding:14px;border-radius:12px;background:#fff1f0;border:1px solid #ffd3cf;color:#9e2f26}.keyboard-hint{font-size:10px;color:#98a0af;margin-top:8px}
