<script>
(function(){
const select=document.getElementById('kanjiSelect'), levelFilter=document.getElementById('levelFilter'), search=document.getElementById('kanjiSearch'), canvas=document.getElementById('writingCanvas'), ctx=canvas.getContext('2d');
const csrfToken=<?php echo json_encode($_SESSION['csrf_token']); ?>;
const status=document.getElementById('canvasStatus'), drawnCount=document.getElementById('drawnCount'), historyEl=document.getElementById('practiceHistory');
const strokeStage=document.getElementById('strokeStage'), strokeStatus=document.getElementById('strokeStatus');
let drawing=false,currentStroke=[],strokes=[],showGuide=true,firstStrokeAt=null,guidePaths=[],revealed=0,animationTimer=null,autoNextTimer=null;
const allOptions=Array.from(select.options);
function option(){return select.options[select.selectedIndex]||allOptions[0]}
function filteredOptions(){const q=search.value.trim().toLocaleLowerCase(),level=levelFilter.value;return allOptions.filter(o=>(level==='ALL'||o.dataset.level===level)&&(!q||[o.dataset.character,o.dataset.meaning,o.dataset.on,o.dataset.kun,o.dataset.level].join(' ').toLocaleLowerCase().includes(q)))}
function syncPosition(){const visible=filteredOptions(),idx=visible.findIndex(o=>o.value===select.value);document.getElementById('kanjiPosition').textContent=(idx>=0?idx+1:1)+' / '+visible.length;document.getElementById('previousKanji').disabled=document.getElementById('previousKanjiText').disabled=visible.length<2||idx<=0;document.getElementById('nextKanji').disabled=document.getElementById('nextKanjiText').disabled=visible.length<2||idx<0||idx>=visible.length-1}
function navigate(delta){const visible=filteredOptions();if(!visible.length)return;let idx=visible.findIndex(o=>o.value===select.value);idx=Math.max(0,Math.min(visible.length-1,idx+delta));if(visible[idx]&&visible[idx].value!==select.value){select.value=visible[idx].value;updateTarget()}}
function draw(){ctx.clearRect(0,0,600,600);ctx.fillStyle='#fbfcff';ctx.fillRect(0,0,600,600);ctx.strokeStyle='#e2e6ef';ctx.lineWidth=1.5;ctx.setLineDash([7,8]);ctx.beginPath();ctx.moveTo(300,18);ctx.lineTo(300,582);ctx.moveTo(18,300);ctx.lineTo(582,300);ctx.stroke();ctx.setLineDash([]);if(showGuide){ctx.fillStyle='rgba(94,105,135,.17)';ctx.font='440px "Yu Gothic","Meiryo",sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(option().dataset.character||'',300,310)}ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#272b45';ctx.lineWidth=15;strokes.concat(currentStroke.length?[currentStroke]:[]).forEach(s=>{if(!s.length)return;ctx.beginPath();ctx.moveTo(s[0].x,s[0].y);for(let i=1;i<s.length;i++)ctx.lineTo(s[i].x,s[i].y);ctx.stroke()});drawnCount.textContent=strokes.length+' stroke'+(strokes.length===1?'':'s')}
function point(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*600/r.width,y:(e.clientY-r.top)*600/r.height}}
canvas.addEventListener('pointerdown',e=>{drawing=true;if(firstStrokeAt===null)firstStrokeAt=Date.now();currentStroke=[point(e)];canvas.setPointerCapture(e.pointerId);draw()});canvas.addEventListener('pointermove',e=>{if(!drawing)return;const p=point(e),last=currentStroke[currentStroke.length-1];if(!last||Math.hypot(p.x-last.x,p.y-last.y)>2.4)currentStroke.push(p);draw()});function finish(){if(!drawing)return;drawing=false;if(currentStroke.length)strokes.push(currentStroke);currentStroke=[];draw();status.textContent='Writing recorded locally. Save when you finish this kanji.';if(document.getElementById('autoNextToggle').checked)checkPractice(true)}canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);
function cancelAutoNext(){if(autoNextTimer!==null){clearTimeout(autoNextTimer);autoNextTimer=null}}
function checkPractice(fromAuto){
 const feedback=document.getElementById('practiceFeedback');cancelAutoNext();
 const expected=guidePaths.length || parseInt(option().dataset.strokes||'0',10);const drawn=strokes.length;
 if(!drawn){feedback.textContent='Draw the kanji first, then check your strokes.';feedback.style.color='#b45309';return false}
 if(!expected){feedback.textContent='Stroke count data is unavailable for this kanji.';feedback.style.color='#b45309';return false}
 if(drawn===expected){
  feedback.textContent='Stroke-count check passed ('+drawn+' / '+expected+'). This checks the number of strokes, not the exact shape or writing order.';feedback.style.color='#15803d';
  if(document.getElementById('autoNextToggle').checked){feedback.textContent+=' Moving to the next kanji in 1.2 seconds…';autoNextTimer=setTimeout(()=>{autoNextTimer=null;navigate(1)},1200)}
  return true;
 }
 feedback.textContent='Not matched yet: you drew '+drawn+' stroke(s), but this kanji should have '+expected+'. Use Undo or Clear and try again.';feedback.style.color='#b45309';return false;
}
function clearCanvas(){cancelAutoNext();const fb=document.getElementById('practiceFeedback');fb.textContent='';fb.style.color='';strokes=[];currentStroke=[];drawing=false;firstStrokeAt=null;draw();status.textContent='Canvas cleared.'}
document.getElementById('checkPracticeButton').addEventListener('click',()=>checkPractice(false));document.getElementById('autoNextToggle').addEventListener('change',()=>{cancelAutoNext();if(!document.getElementById('autoNextToggle').checked){const fb=document.getElementById('practiceFeedback');fb.textContent=fb.textContent.replace(' Moving to the next kanji in 1.2 seconds…','')}});
document.getElementById('clearButton').addEventListener('click',clearCanvas);document.getElementById('undoButton').addEventListener('click',()=>{cancelAutoNext();strokes.pop();currentStroke=[];document.getElementById('practiceFeedback').textContent='';draw();status.textContent='Last stroke undone.'});document.getElementById('guideButton').addEventListener('click',()=>{showGuide=!showGuide;draw();document.getElementById('guideButton').textContent=showGuide?'Hide guide':'Show guide'});
function stopAnimation(){if(animationTimer!==null){clearTimeout(animationTimer);animationTimer=null}}
function updateRevealed(){guidePaths.forEach((p,i)=>{p.style.opacity=i<revealed?'1':'0';p.style.fill=(i===revealed-1&&revealed>0)?'#5b5ce2':'#272b45'});strokeStatus.textContent=guidePaths.length?'Stroke '+revealed+' of '+guidePaths.length+(revealed===guidePaths.length?' · Complete!':''):'Stroke order is unavailable for this kanji.'}
function nextStroke(){stopAnimation();if(guidePaths.length&&revealed<guidePaths.length){revealed++;updateRevealed()}}
function play(){stopAnimation();if(!guidePaths.length)return;revealed=0;updateRevealed();function step(){if(revealed>=guidePaths.length){animationTimer=null;return}revealed++;updateRevealed();animationTimer=setTimeout(step,560)}animationTimer=setTimeout(step,180)}
async function loadStrokeOrder(character){stopAnimation();guidePaths=[];revealed=0;strokeStage.innerHTML='<div class="placeholder">Loading stroke order…</div>';strokeStatus.textContent='Loading stroke paths…';const cp=character.codePointAt(0).toString(16).padStart(5,'0');try{const res=await fetch('https://raw.githubusercontent.com/KanjiVG/kanjivg/master/kanji/'+cp+'.svg');if(!res.ok)throw Error();const parsed=new DOMParser().parseFromString(await res.text(),'image/svg+xml'),src=parsed.querySelector('svg');if(!src)throw Error();const svg=document.importNode(src,true);svg.removeAttribute('width');svg.removeAttribute('height');svg.setAttribute('viewBox',src.getAttribute('viewBox')||'0 0 109 109');svg.setAttribute('aria-label','Stroke order for '+character);const paths=Array.from(svg.querySelectorAll('path[id*="-s"]')).filter(p=>/-s\d+$/.test(p.id)).sort((a,b)=>Number((a.id.match(/-s(\d+)$/)||[0,0])[1])-Number((b.id.match(/-s(\d+)$/)||[0,0])[1]));if(!paths.length)throw Error();svg.querySelectorAll('[id*="StrokeNumbers"]').forEach(n=>n.remove());paths.forEach(p=>{p.style.fill='#272b45';p.style.opacity='0';p.style.transition='opacity 160ms ease';p.removeAttribute('class');guidePaths.push(p)});strokeStage.replaceChildren(svg);updateRevealed()}catch(e){strokeStage.innerHTML='<div class="placeholder">Stroke-order data is not available. You can still practise on the board.</div>';strokeStatus.textContent='Try another kanji or check your internet connection.'}}
function updateTarget(){const o=option();document.getElementById('targetCharacter').textContent=o.dataset.character||'';document.getElementById('targetMeaning').textContent=o.dataset.meaning||'';document.getElementById('targetOn').textContent=o.dataset.on||'—';document.getElementById('targetKun').textContent=o.dataset.kun||'—';document.getElementById('targetLevel').textContent=o.dataset.level||'';document.getElementById('targetStrokes').textContent=o.dataset.strokes||'—';history.replaceState(null,'','practice.php?kanji_id='+encodeURIComponent(o.value));clearCanvas();syncPosition();loadStrokeOrder(o.dataset.character||'')}
function applyFilters(preferFirst){const visible=filteredOptions();Array.from(select.options).forEach(o=>{o.hidden=!visible.includes(o)});if(visible.length&&(!visible.some(o=>o.value===select.value)||preferFirst)){select.value=visible[0].value;updateTarget()}else{syncPosition()}}
levelFilter.addEventListener('change',()=>applyFilters(true));
select.addEventListener('change',updateTarget);search.addEventListener('input',()=>applyFilters(false));['previousKanji','previousKanjiText'].forEach(id=>document.getElementById(id).addEventListener('click',()=>navigate(-1)));['nextKanji','nextKanjiText'].forEach(id=>document.getElementById(id).addEventListener('click',()=>navigate(1)));document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;if(document.activeElement===search||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();navigate(-1)}if(e.key==='ArrowRight'){e.preventDefault();navigate(1)}});
document.getElementById('playStrokeButton').addEventListener('click',play);document.getElementById('nextStrokeButton').addEventListener('click',nextStroke);document.getElementById('resetStrokeButton').addEventListener('click',()=>{stopAnimation();revealed=0;updateRevealed()});
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function loadHistory(){try{const r=await fetch('save_practice.php?action=history',{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw Error();if(!d.attempts.length){historyEl.innerHTML='<div class="empty-history">No attempts saved yet. Your latest practice will show here.</div>';return}historyEl.innerHTML=d.attempts.slice(0,6).map(a=>'<div class="history-item"><div class="history-char">'+esc(a.kanji_character)+'</div><div class="history-detail"><strong>'+esc(a.meaning)+'</strong><small>'+Number(a.stroke_count)+' drawn · '+esc(a.created_at)+'</small></div></div>').join('')}catch(e){historyEl.innerHTML='<div class="empty-history">History will appear here after your first save.</div>'}}
document.getElementById('savePracticeButton').addEventListener('click',async()=>{const o=option(),btn=document.getElementById('savePracticeButton');if(!strokes.length){status.textContent='Write at least one stroke before saving.';return}btn.disabled=true;btn.textContent='Saving…';try{const payload={csrf_token:csrfToken,kanji_id:Number(o.value),stroke_count:strokes.length,duration_seconds:firstStrokeAt===null?0:Math.max(0,Math.round((Date.now()-firstStrokeAt)/1000))};const r=await fetch('save_practice.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});const responseText=await r.text();let d;try{d=JSON.parse(responseText)}catch(parseError){console.error('Save practice returned non-JSON:',responseText);throw Error('The server returned an invalid response instead of JSON. Check save_practice.php for a PHP error; open the browser Console or send me the exact response.')};if(!r.ok||!d.success)throw Error(d.message||('Save failed (HTTP '+r.status+').'));status.textContent='Saved! Your practice history has been updated.';await loadHistory()}catch(e){status.textContent=e.message||'Could not save practice. Check that MySQL is running.'}finally{btn.disabled=false;btn.textContent='Save practice ↗'}});
levelFilter.value=option().dataset.level||'ALL';applyFilters(false);draw();syncPosition();loadStrokeOrder(option().dataset.character||'');loadHistory();
})();
</script>
<?php endif; ?>
</body></html>
